# Turns a model generated by Meshy (a textured .glb) into a rigid model the
# game can serve, and renders a sheet to judge it by before it goes in a mod.
#
#   flatpak run org.blender.Blender --background --python tools/meshy_prop.py -- \
#       IN.glb OUT_DIR NAME --height 1.2 [--origin base|centre] [--tris 3000] \
#       [--tex 128] [--colours 24]
#
# What it does, in order:
#   * joins every mesh, drops the scene's transforms, sizes the model so it is
#     --height metres tall (the robot is 1.357) and puts its origin at the
#     middle of its base (base) or of its box (centre);
#   * decimates to about --tris triangles, keeping the UVs;
#   * shrinks the texture to --tex pixels and reduces it to --colours colours
#     (k-means), so a Meshy painting reads like the game's flat 32 px blocks
#     instead of a photograph, and the edges between colours follow the
#     texture, not the triangles;
#   * exports OUT_DIR/NAME.gltf + NAME.bin + NAME.png (each under the 1 MB a
#     media file may weigh);
#   * renders ~/.cache/cnp_look/NAME_sheet.png: front, side, back, three
#     quarters, each beside the robot for scale. Nothing goes in a mod until
#     that sheet has been looked at.
#
# Meshy is for rigid things here: props, decor, held items, statues, vehicles'
# bodies. Bending a generated character onto the robot's rig did not work (the
# mole of 2026-11-07, reverted).
import math
import os
import sys

import bmesh
import bpy
import numpy as np
from mathutils import Vector

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
ROBOT = os.path.join(ROOT, "mods", "robot", "robot.gltf")
LOOK = os.path.expanduser("~/.cache/cnp_look")
MAX_MEDIA = 1 << 20


def args():
    argv = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else []
    opt = {"--height": 1.0, "--origin": "base", "--tris": 3000, "--tex": 128, "--colours": 24}
    pos = []
    i = 0
    while i < len(argv):
        if argv[i] in opt:
            opt[argv[i]] = type(opt[argv[i]])(argv[i + 1])
            i += 2
        else:
            pos.append(argv[i])
            i += 1
    if len(pos) != 3:
        sys.exit("usage: meshy_prop.py -- IN.glb OUT_DIR NAME [--height m] [--origin base|centre] "
                 "[--tris n] [--tex px] [--colours n]")
    return pos, opt


def clear():
    bpy.ops.wm.read_factory_settings(use_empty=True)


def load(path):
    bpy.ops.import_scene.gltf(filepath=path)
    meshes = [o for o in bpy.context.scene.objects if o.type == "MESH"]
    for o in bpy.context.scene.objects:
        o.select_set(o in meshes)
    bpy.context.view_layer.objects.active = meshes[0]
    if len(meshes) > 1:
        bpy.ops.object.join()
    ob = bpy.context.view_layer.objects.active
    ob.parent = None
    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)
    for o in list(bpy.context.scene.objects):
        if o is not ob:
            bpy.data.objects.remove(o)
    return ob


def place(ob, height, origin):
    vs = np.array([v.co[:] for v in ob.data.vertices])
    lo, hi = vs.min(0), vs.max(0)
    s = height / (hi[2] - lo[2])
    centre = (lo + hi) / 2
    pivot = Vector((centre[0], centre[1], lo[2] if origin == "base" else centre[2]))
    for v in ob.data.vertices:
        v.co = (v.co - pivot) * s


def decimate(ob, tris):
    have = sum(len(p.vertices) - 2 for p in ob.data.polygons)
    if have > tris:
        m = ob.modifiers.new("dec", "DECIMATE")
        m.ratio = tris / have
        bpy.context.view_layer.objects.active = ob
        bpy.ops.object.modifier_apply(modifier=m.name)
    bm = bmesh.new()
    bm.from_mesh(ob.data)
    bmesh.ops.triangulate(bm, faces=bm.faces)
    bm.to_mesh(ob.data)
    bm.free()
    for p in ob.data.polygons:
        p.use_smooth = False


def kmeans(px, k, rounds=12):
    rng = np.random.default_rng(1)
    c = px[rng.choice(len(px), k, replace=False)]
    for _ in range(rounds):
        lab = ((px[:, None, :] - c[None]) ** 2).sum(2).argmin(1)
        for j in range(k):
            if (lab == j).any():
                c[j] = px[lab == j].mean(0)
    return c, lab


def texture(ob, name, size, colours, out_dir):
    mat = ob.data.materials[0]
    node = next(n for n in mat.node_tree.nodes if n.type == "TEX_IMAGE")
    img = node.image
    img.scale(size, size)
    px = np.array(img.pixels[:]).reshape(-1, 4)
    c, lab = kmeans(px[:, :3].copy(), colours)
    px[:, :3] = c[lab]
    px[:, 3] = 1.0
    small = bpy.data.images.new(name, size, size, alpha=False)
    small.pixels = px.ravel().tolist()
    small.filepath_raw = os.path.join(out_dir, name + ".png")
    small.file_format = "PNG"
    small.save()
    # one plain material, the texture and nothing else: the game reads base colour only
    for m in list(ob.data.materials):
        ob.data.materials.pop()
    new = bpy.data.materials.new(name)
    new.use_nodes = True
    bsdf = next(n for n in new.node_tree.nodes if n.type == "BSDF_PRINCIPLED")
    bsdf.inputs["Metallic"].default_value = 0.0
    bsdf.inputs["Roughness"].default_value = 1.0
    tex = new.node_tree.nodes.new("ShaderNodeTexImage")
    tex.image = small
    tex.interpolation = "Closest"
    new.node_tree.links.new(tex.outputs["Color"], bsdf.inputs["Base Color"])
    ob.data.materials.append(new)


def export(ob, out_dir, name):
    ob.name = ob.data.name = name
    path = os.path.join(out_dir, name + ".gltf")
    bpy.ops.object.select_all(action="DESELECT")
    ob.select_set(True)
    bpy.ops.export_scene.gltf(filepath=path, export_format="GLTF_SEPARATE", use_selection=True,
                              export_image_format="AUTO", export_apply=True, export_animations=False)
    for ext in (".gltf", ".bin", ".png"):
        size = os.path.getsize(os.path.join(out_dir, name + ext))
        print(f"{name}{ext}: {size} bytes")
        assert size < MAX_MEDIA, f"{name}{ext} is over 1 MB"
    print(f"{name}: {len(ob.data.polygons)} triangles, {len(ob.data.vertices)} vertices")


def sheet(ob, name):
    bpy.ops.import_scene.gltf(filepath=ROBOT)
    robot = [o for o in bpy.context.scene.objects if o is not ob]
    w = max(ob.dimensions.x, ob.dimensions.y) / 2 + 0.6
    for o in robot:
        if o.parent is None:
            o.location.x += w
    scene = bpy.context.scene
    scene.render.engine = "BLENDER_EEVEE_NEXT" if "BLENDER_EEVEE_NEXT" in [
        e.identifier for e in bpy.types.RenderSettings.bl_rna.properties["engine"].enum_items] else "BLENDER_EEVEE"
    scene.render.resolution_x = scene.render.resolution_y = 512
    scene.render.film_transparent = False
    world = bpy.data.worlds.new("w")
    world.use_nodes = True
    world.node_tree.nodes["Background"].inputs[0].default_value = (0.45, 0.5, 0.55, 1)
    world.node_tree.nodes["Background"].inputs[1].default_value = 1.0
    scene.world = world
    sun = bpy.data.objects.new("sun", bpy.data.lights.new("sun", "SUN"))
    sun.data.energy = 3
    sun.rotation_euler = (math.radians(50), 0, math.radians(30))
    scene.collection.objects.link(sun)
    cam = bpy.data.objects.new("cam", bpy.data.cameras.new("cam"))
    cam.data.type = "ORTHO"
    scene.collection.objects.link(cam)
    scene.camera = cam
    top = max(ob.dimensions.z, 1.4)
    cx = w / 2
    cam.data.ortho_scale = max(top, 2 * w + 0.6) * 1.1
    shots = []
    for k, yaw in enumerate((0, 90, 180, 35)):
        a = math.radians(yaw)
        d = 10
        cam.location = (cx + d * math.sin(a), -d * math.cos(a), top / 2 + (1.5 if yaw == 35 else 0))
        cam.rotation_euler = ((math.atan2(d, 1.5 if yaw == 35 else 0)), 0, a)
        for o in robot:
            o.hide_render = k != 0   # the robot for scale in front only
        cx = w / 2 if k == 0 else 0
        cam.location = (cx + d * math.sin(a), -d * math.cos(a), top / 2 + (1.5 if yaw == 35 else 0))
        path = os.path.join(LOOK, f"{name}_v{k}.png")
        scene.render.filepath = path
        bpy.ops.render.render(write_still=True)
        shots.append(path)
    imgs = [bpy.data.images.load(p) for p in shots]
    out = bpy.data.images.new(name + "_sheet", 1024, 1024)
    big = np.zeros((1024, 1024, 4))
    for k, im in enumerate(imgs):
        p = np.array(im.pixels[:]).reshape(512, 512, 4)
        r, c = 1 - k // 2, k % 2
        big[r * 512:(r + 1) * 512, c * 512:(c + 1) * 512] = p
    out.pixels = big.ravel().tolist()
    out.filepath_raw = os.path.join(LOOK, name + "_sheet.png")
    out.file_format = "PNG"
    out.save()
    for p in shots:
        os.remove(p)
    print("sheet:", out.filepath_raw)


def main():
    (src, out_dir, name), opt = args()
    os.makedirs(out_dir, exist_ok=True)
    os.makedirs(LOOK, exist_ok=True)
    clear()
    ob = load(src)
    place(ob, opt["--height"], opt["--origin"])
    decimate(ob, opt["--tris"])
    texture(ob, name, opt["--tex"], opt["--colours"], out_dir)
    export(ob, out_dir, name)
    sheet(ob, name)


if __name__ == "__main__":
    main()
